<?php
$o=query('SELECT * FROM orders WHERE id=?',[(int)($_GET['id']??0)])->fetch();
if(!$o){http_response_code(404);echo '<p>주문을 찾을 수 없습니다.</p>';return;}
$items=orderItems((int)$o['id']);$b=balance($o,$items);$historical=(bool)$o['import_batch_id'];$locked=$historical || (bool)$o['paid'] || (bool)$o['cancelled'];
$customerPayer=(string)(query('SELECT payer_name FROM customers WHERE id=?',[$o['customer_id']])->fetchColumn()?:'');
$payments=query('SELECT * FROM payments WHERE order_id=? ORDER BY id',[$o['id']])->fetchAll();
$allocations=query('SELECT a.item_id,SUM(a.amount_cents) amount FROM payment_allocations a JOIN payments p ON p.id=a.payment_id WHERE p.order_id=? GROUP BY a.item_id',[$o['id']])->fetchAll(PDO::FETCH_KEY_PAIR);
?>
<?php if($historical): ?><div class="notice">과거 엑셀에서 가져온 조회 전용 주문입니다. 실제 배송일·입금일·받는 방법은 미기록입니다.<?php $trace=query("SELECT source_ref FROM import_records WHERE entity_type='orders' AND target_id=?",[$o['id']])->fetchColumn(); ?> 원본 위치: <?=e($trace?:'미확인')?></div><?php endif ?><div class="toolbar"><a href="/?page=orders">← 주문 목록</a><div class="actions"><?php if(!$locked): ?><a class="button secondary" href="/?page=order-edit&id=<?=(int)$o['id']?>">주문 수정·대기 제품 취소</a><?php endif ?><button class="button secondary" id="print-order">주문서 인쇄</button></div></div>
<?php if($o['cancelled']): ?><div class="alert">취소한 주문입니다. 취소 이력은 아래에 보관됩니다.</div><?php elseif($o['paid']): ?><div class="alert success">✓ 입금 완료 · 이 주문은 수정·취소할 수 없습니다.</div><?php elseif($b['received']): ?><div class="notice">일부 입금된 주문입니다. 이미 전달한 수량과 입금 기록은 보존하며, 대기 수량만 수정·취소할 수 있습니다.</div><?php endif ?>
<div class="stats three"><article><p>최종 주문 금액</p><strong><?=money($b['total'])?></strong><span>취소 제품 제외 · 배달비 포함</span></article><article><p>지금까지 받은 금액</p><strong><?=money($b['received'])?></strong><span><?=count($payments)?>회 입금</span></article><article class="warm"><p>전체 남은 금액</p><strong><?=money(max(0,$b['total']-$b['received']))?></strong><span>아직 전달하지 않은 제품 포함</span></article></div>
<div class="detail-layout"><div class="stack"><section class="panel"><div class="section-title"><h2>주문 #<?=str_pad((string)$o['id'],4,'0',STR_PAD_LEFT)?></h2><span><?=e($o['order_date'])?> 주문</span></div><h2><a href="/?page=customer&id=<?=(int)$o['customer_id']?>"><?=e($o['customer_name'])?></a></h2><div class="delivery-info"><strong><?=e($o['delivery_date']??'날짜 미기록')?> · <?=e(['pickup'=>'직접 픽업','delivery'=>'집으로 배달','unknown'=>'받는 방법 미기록'][$o['fulfillment']])?></strong><p><?=e($o['delivery_address'])?></p><small>대기 제품이 있으면 다음 전달 예정일입니다. 실제 전달일은 이력에 남습니다.</small></div>
<div class="table-wrap"><table class="item-table"><thead><tr><th>제품 / 단가</th><th>주문</th><th>전달</th><th>대기</th><th>취소</th><th>제품 금액</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=e($i['product_code'])?> · <?=e($i['product_name'])?><small><?=weight($i['weight_g'])?> · <?=money((int)$i['unit_price_cents'])?></small><?php if($i['delivered_quantity']): ?><small>🔒 전달 수량 보존<?php if((int)($allocations[$i['id']]??0)): ?> · 입금 <?=money((int)$allocations[$i['id']])?><?php endif ?></small><?php endif ?></td><td><?=(int)$i['quantity']?></td><td><?=(int)$i['delivered_quantity']?></td><td><?=pendingQty($i)?></td><td><?=(int)$i['cancelled_quantity']?></td><td><?=money(itemNet($i,activeQty($i)))?></td></tr><?php endforeach ?></tbody></table></div>
<div class="totals"><p>제품 합계 <strong><?=money($b['subtotal'])?></strong></p><p>할인액 <strong>− <?=money($b['discount'])?></strong></p><p>배달비 <strong><?=money($b['fee'])?></strong></p><?php foreach(['other_sales_cents'=>'기타 판매 (김밥)','other_charges_cents'=>'기타 청구'] as $k=>$label): if($o[$k]): ?><p><?=$label?> <strong><?=money((int)$o[$k])?></strong></p><?php endif;endforeach ?><h2>받을 금액 <strong><?=money($b['total'])?></strong></h2></div><?php if($o['additional_income_cents']): ?><div class="notice">동의받은 추가 수입 <?=money((int)$o['additional_income_cents'])?> · 김치 매출과 별도 · 전체 입금 합계 <?=money($b['received']+(int)$o['additional_income_cents'])?></div><?php endif ?><?php if($o['notes']!==''): ?><div class="notice">주문 메모<br><?=nl2br(e($o['notes']))?></div><?php endif ?></section>
<section class="panel"><h2>입금 내역</h2><?php if(!$payments): ?><p class="muted">아직 기록한 입금이 없습니다.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>입금일</th><th>방법</th><th>입금자 성명</th><th>금액</th><th>메모</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?=e($p['paid_on']??'기존 기록 · 날짜 미기록')?></td><td><?=e(['cash'=>'현금','etransfer'=>'eTransfer','legacy'=>'기존 입금'][$p['method']]??$p['method'])?></td><td><?=e($p['payer_name']?:'미기록')?></td><td><?=money((int)$p['amount_cents'])?></td><td><?=e($p['note'])?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<section class="panel"><h2>주문 처리 이력 · 최근 100건</h2><?php foreach(query('SELECT e.*,u.username FROM order_events e JOIN users u ON u.id=e.created_by WHERE e.order_id=? ORDER BY e.id DESC LIMIT 100',[$o['id']])->fetchAll() as $ev): $detail=json_decode($ev['detail'],true); ?><article class="history-entry"><small><?=e($ev['created_at'])?> · <?=e($ev['username'])?></small><p><?=e($ev['summary'])?></p><?php if($ev['kind']==='edit_order'): ?><?php foreach($detail['items']??[] as $change): ?><small><?=e($change['product'])?>: <?=isset($change['added'])?'추가 '.(int)$change['added'].'개':'대기 '.(int)$change['pending_before'].' → '.(int)$change['pending_after'].'개'?></small><br><?php endforeach ?><?php if(($detail['previous_date']??'')!==($detail['next_date']??'')): ?><small>예정일 <?=e($detail['previous_date'])?> → <?=e($detail['next_date'])?></small><?php endif ?><?php endif ?></article><?php endforeach ?></section></div>
<aside class="stack no-print"><?php if(!$historical && !$o['cancelled'] && $b['pending']): ?><section class="panel"><h2>이번에 전달한 제품</h2><p class="hint">전달한 제품만 수량을 입력하세요. 나머지는 대기로 남습니다.</p><form method="post" class="stack"><?=workflowFields($o,'deliver_items')?><label>실제 전달일<input type="date" name="delivered_on" value="<?=date('Y-m-d')?>" max="<?=date('Y-m-d')?>" min="<?=e($o['order_date'])?>" required></label><?php foreach($items as $i): if(!pendingQty($i)) continue; ?><label><?=e($i['product_code'])?> · <?=e($i['product_name'])?> <small>(대기 <?=pendingQty($i)?>개)</small><input type="number" name="deliver[<?=(int)$i['id']?>]" min="0" max="<?=pendingQty($i)?>" value="0" step="1"></label><?php endforeach ?><button class="button full">선택 수량 전달 완료</button></form><details class="minor-action"><summary>남은 제품을 모두 전달했나요?</summary><form method="post"><?=workflowFields($o,'deliver_all')?><input type="hidden" name="delivered_on" value="<?=date('Y-m-d')?>"><button class="button secondary full">전달 완료로 표시</button></form></details></section><?php elseif($o['delivered']): ?><section class="panel"><h2>배달·픽업 확인</h2><p class="status-big">✓ 전달 완료</p></section><?php endif ?>
<section class="panel"><h2>입금 기록하기</h2><p class="muted">이번 전달분 미입금</p><p class="status-big"><?=money($b['collectable'])?></p><?php if(!$locked && $b['collectable']>0): ?><form method="post" class="stack"><?=workflowFields($o,'receive_payment')?><label>실제로 받은 금액 ($)<input type="number" name="amount" step="0.01" min="0.01" max="<?=number_format($b['collectable']/100,2,'.','')?>" value="<?=number_format($b['collectable']/100,2,'.','')?>" required></label><label>입금 방법<select name="payment_method"><option value="etransfer">eTransfer</option><option value="cash">현금</option></select></label><label>입금일<input type="date" name="paid_on" value="<?=date('Y-m-d')?>" min="<?=e($o['order_date'])?>" max="<?=date('Y-m-d')?>" required></label><label>이번 입금자 성명 (선택)<input name="payer_name" maxlength="100" value="<?=e(pv('payer_name'))?>" placeholder="은행에 표시된 이름 그대로"></label><?php if($customerPayer!==''): ?><p class="hint">주로 입금하는 분: <?=e($customerPayer)?> · 이번 입금자와 일치하는지 확인 후 입력하세요.</p><?php endif ?><p class="hint">빈칸이면 ‘미기록’으로 남습니다. 고객 이름을 자동으로 넣지 않습니다.</p><label>입금 메모<input name="payment_note" maxlength="500" placeholder="선택 사항"></label><button class="button full">입금 기록하기</button></form><?php elseif($o['paid']): ?><p>✓ 입금 완료</p><?php elseif(!$o['cancelled']): ?><p class="hint"><?=$b['shipped']?'전달한 제품의 대금은 모두 받았습니다. 나머지는 전달 후 추가 입금하세요.':'제품을 전달한 뒤 입금을 기록하세요.'?></p><?php endif ?></section>
<?php if(!$locked && !$b['shipped'] && !$b['received']): ?><section class="panel"><details><summary>주문 전체 취소</summary><form method="post" class="stack minor-action"><?=workflowFields($o,'cancel_order')?><label>취소 사유<input name="reason" maxlength="400" required placeholder="예: 고객 요청 / 중복 주문"></label><p class="hint">주문을 삭제하지 않고 취소 기록으로 보관합니다.</p><button class="button danger full" data-confirm="이 주문 전체를 취소할까요?">주문 전체 취소하기</button></form></details></section><?php endif ?></aside></div>
